}

.promo-banner strong {
  font-weight: 700;
}

/* Hero Carousel */
.hero-section {
  padding: 3rem 0;
  background: var(--muted);
}

.hero-carousel {
  position: relative;
  overflow: hidden;
}

.hero-carousel-track {
  display: flex;
