const { chromium } = require('playwright');
const path = require('path');
const fs = require('fs');

async function testPages() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  const pages = ['index.html', 'courses.html', 'projects.html', 'plus.html', 'login.html'];
  const errors = [];

  page.on('console', msg => {
    if (msg.type() === 'error') {
      errors.push({ page: currentPage, error: msg.text() });
    }
  });

  page.on('pageerror', error => {
    errors.push({ page: currentPage, error: error.message });
  });

  let currentPage = '';

  for (const htmlPage of pages) {
    currentPage = htmlPage;
    const filePath = path.join(__dirname, 'output', htmlPage);
    console.log(`Testing: ${htmlPage}`);

    try {
      await page.goto(`file://${filePath}`, { waitUntil: 'domcontentloaded' });
      await page.waitForTimeout(500);
      console.log(`  ✓ ${htmlPage} loaded`);
    } catch (e) {
      console.log(`  ✗ ${htmlPage} failed: ${e.message}`);
    }
  }

  await browser.close();

  if (errors.length > 0) {
    console.log('\nConsole Errors:');
    errors.forEach(e => console.log(`  - ${e.page}: ${e.error}`));
  } else {
    console.log('\n✓ No console errors detected');
  }
}

testPages().catch(console.error);

